a<-commandArgs(TRUE);p<-a[1];s<-read.csv(file.path(p,'summary.csv'));d<-subset(s,type=='threshold_change' & metric %in% c('births','deaths'));keys<-c('48 fixed','96 fixed','48 staggered','96 staggered');bb<-d[match(paste(keys,'births'),paste(d$label,d$metric)),];dd<-d[match(paste(keys,'deaths'),paste(d$label,d$metric)),];stopifnot(!anyNA(bb$mean),!anyNA(dd$mean));ylim<-range(c(0,bb$lower,bb$upper,-dd$upper,-dd$lower));png(file.path(p,'birth-death-components.png'),width=1400,height=850,res=160);par(mar=c(7,5,3,1));plot(NA,xlim=c(.5,4.5),ylim=ylim,xaxt='n',xlab='',ylab='Contribution to change in food effect (individuals)',main='Demographic components of lowering the reproductive threshold');abline(h=0,lty=2,col='gray50');axis(1,at=1:4,labels=c('48 founders\nSame ages','96 founders\nSame ages','48 founders\nStaggered ages','96 founders\nStaggered ages'),tick=FALSE,line=.2);x<-1:4-.09;arrows(x,bb$lower,x,bb$upper,angle=90,code=3,length=.04,col='#2166ac');points(x,bb$mean,pch=16,col='#2166ac');x<-1:4+.09;arrows(x,-dd$upper,x,-dd$lower,angle=90,code=3,length=.04,col='#b2182b');points(x,-dd$mean,pch=17,col='#b2182b');legend('topright',legend=c('Birth component','Death component (sign reversed)'),pch=c(16,17),col=c('#2166ac','#b2182b'),bty='n');mtext('Components sum to the population contrast; 95% paired intervals',side=1,line=5,cex=.8);dev.off()
